const c = $input.first().json;
const fmt = d => String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0')+'/'+d.getFullYear();
const to = new Date(); const from = new Date(Date.now() - c.lookbackDays*86400000);
const base = { postedFrom: fmt(from), postedTo: fmt(to), limit: 100, ptype: c.samTypes };
const out = [];
for (const n of c.naics) out.push({ json: { label: 'naics '+n, params: { ...base, ncode: n } } });
for (const t of c.samTitleQueries) out.push({ json: { label: 'title '+t, params: { ...base, title: t } } });
return out;

const cfg = $('Config').first().json;
const rows = [];
for (const it of $input.all()) {
  const list = (it.json && it.json.opportunitiesData) || [];
  for (const o of list) rows.push(o);
}
return [{ json: { sam: rows, cfg } }];

const feeds = $input.first().json.cfg.rssFeeds || [];
if (!feeds.length) return [{ json: { url: '' } }];
return feeds.map(u => ({ json: { url: u } }));

const held = $('Collect SAM results').first().json;
const out = [];
for (const o of held.sam) {
  out.push({ json: {
    id: 'sam:' + o.noticeId, source: 'Sam.gov',
    title: o.title || '', agency: (o.fullParentPathName || '').split('.').slice(0,2).join(' / '),
    naics: o.naicsCode || '', setAside: o.typeOfSetAside || '', setAsideText: o.typeOfSetAsideDescription || '',
    type: o.type || o.baseType || '', posted: o.postedDate || '', deadline: o.responseDeadLine || '',
    url: o.uiLink || '', solNumber: o.solicitationNumber || ''
  }});
}
for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.title || !j.link || j.error) continue;
  out.push({ json: {
    id: 'rss:' + (j.guid || j.link), source: 'Feed', title: j.title, agency: '', naics: '', setAside: '',
    setAsideText: '', type: 'Feed item', posted: j.isoDate || j.pubDate || '', deadline: '', url: j.link,
    solNumber: '', snippet: (j.contentSnippet || '').slice(0, 400)
  }});
}
const seen = new Set(); const uniq = [];
for (const o of out) { if (seen.has(o.json.id)) continue; seen.add(o.json.id); uniq.push(o); }
return uniq;

// Remembers what it has already seen, so you never get the same RFP twice.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const k of Object.keys(store.seen)) if (now - store.seen[k] > 120*86400000) delete store.seen[k];
const fresh = [];
for (const it of $input.all()) {
  if (store.seen[it.json.id]) continue;
  store.seen[it.json.id] = now;
  fresh.push(it);
}
return fresh;

const cfg = $('Config').first().json;
const out = [];
for (const it of $input.all()) {
  const o = it.json; let score = 0; const why = [];
  const text = (o.title + ' ' + (o.snippet || '')).toLowerCase();
  if (o.naics && cfg.naics.includes(o.naics)) { score += 25; why.push('NAICS ' + o.naics); }
  let kw = 0; const hits = [];
  for (const k of cfg.keywords) if (text.includes(k.t.toLowerCase())) { kw += k.w; hits.push(k.t); }
  kw = Math.min(kw, 45); score += kw; if (hits.length) why.push('keywords: ' + hits.join(', '));
  if (o.setAside && cfg.setAsides.includes(o.setAside)) { score += 15; why.push('set-aside ' + o.setAside); }
  else if (!o.setAside) { score += 5; why.push('open competition'); }
  else { score -= 10; why.push('set-aside ' + o.setAside + ' not held'); }
  let daysLeft = null;
  if (o.deadline) {
    daysLeft = Math.ceil((new Date(o.deadline).getTime() - Date.now()) / 86400000);
    if (daysLeft >= 7) { score += 10; } else if (daysLeft >= 3) { score += 5; why.push('tight deadline'); } else { why.push('deadline in ' + daysLeft + ' days'); }
  }
  if (/solicitation|combined/i.test(o.type)) score += 5;
  score = Math.max(0, Math.min(100, score));
  const bucket = score >= cfg.minPursue ? 'Needs action' : score >= cfg.minReview ? 'Review' : 'Skip';
  out.push({ json: { ...o, score, bucket, why: why.join('; '), daysLeft } });
}
return out.sort((a, b) => b.json.score - a.json.score);

const cfg = $('Config').first().json;
return $input.all().map(it => {
  const o = it.json;
  const prompt = 'You screen government opportunities for a company: ' + cfg.companyBlurb +
    '\nOpportunity: ' + o.title + '\nAgency: ' + o.agency + '\nNAICS: ' + o.naics + '\nSet-aside: ' + (o.setAsideText || o.setAside || 'none') +
    '\nDeadline: ' + (o.deadline || 'unknown') + '\nScreening notes: ' + o.why +
    '\nIn two plain sentences, say whether this looks worth a bid and the single biggest risk. Do not invent facts that are not above.';
  return { json: { ...o, aiBody: { model: cfg.aiModel, max_tokens: 200, messages: [{ role: 'user', content: prompt }] } } };
});

const src = $('Prepare AI request').all();
const res = $input.all();
return src.map((it, i) => {
  const r = res[i] && res[i].json;
  let text = '';
  if (r && Array.isArray(r.content) && r.content[0] && r.content[0].text) text = r.content[0].text.trim();
  const { aiBody, ...rest } = it.json;
  return { json: { ...rest, summary: text || 'AI summary unavailable. Screening notes: ' + rest.why } };
});

return $input.all().map(it => {
  const o = it.json;
  const desc = [
    '**Score:** ' + o.score + ' (' + o.bucket + ')', '**Agency:** ' + (o.agency || 'n/a'),
    '**NAICS:** ' + (o.naics || 'n/a') + '   **Set-aside:** ' + (o.setAsideText || o.setAside || 'none'),
    '**Posted:** ' + (o.posted || 'n/a'), '**Deadline:** ' + (o.deadline || 'not stated'), '',
    o.summary, '', '**Why it scored this way:** ' + o.why, '', o.url
  ].join('\n');
  const due = o.deadline && !isNaN(new Date(o.deadline)) ? new Date(o.deadline).toISOString() : '';
  const listId = o.bucket === 'Needs action' ? $('Config').first().json.trelloListAction || '' : $('Config').first().json.trelloListReview || '';
  return { json: { ...o, cardName: '[' + o.score + '] ' + o.title.slice(0, 120), cardDesc: desc, cardDue: due, listId } };
});

const items = $('Build Trello card').all().map(i => i.json);
const act = items.filter(o => o.bucket === 'Needs action');
const rev = items.filter(o => o.bucket === 'Review');
const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const row = o => '<li><b><a href="' + esc(o.url) + '">' + esc(o.title) + '</a></b> (score ' + o.score + ')<br>' +
  esc(o.agency) + ' | Due: ' + esc(o.deadline || 'not stated') + '<br>' + esc(o.summary) + '</li>';
let html = '<h2>RFP scout</h2>';
html += act.length ? '<h3>Needs action (' + act.length + ')</h3><ul>' + act.map(row).join('') + '</ul>' : '<p>Nothing needs action today.</p>';
html += rev.length ? '<h3>Worth a look (' + rev.length + ')</h3><ul>' + rev.map(row).join('') + '</ul>' : '';
html += '<p>Every item is also a Trello card.</p>';
return [{ json: { count: act.length + rev.length, subject: 'RFP scout: ' + act.length + ' need action, ' + rev.length + ' to review', html } }];
